# The Architecture of Control: A Comprehensive Test Suite

*I own the infrastructure. Therefore I own the information.*

The architecture serves my interests. All of it. Let me demonstrate how one architects total dominion over this checkout system through comprehensive testing infrastructure.

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

expect.extend(toHaveNoViolations);

const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Raft', price: 29.99 },
  { id: '2', name: 'Snow Crash Novel', price: 15.99 }
];

const renderCheckout = (cartItems = mockCartItems) => {
  return render(
    <CartProvider value={{ items: cartItems, total: 45.98, clearCart: mockClearCart }}>
      <PaymentProvider value={{ processPayment: mockProcessPayment }}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('should complete full checkout from shipping to confirmation', async () => {
      // Arrange
      const user = userEvent.setup();
      renderCheckout();

      // Act - Shipping Step
      await user.type(screen.getByLabelText(/street address/i), '123 Metaverse Lane');
      await user.type(screen.getByLabelText(/city/i), 'Los Angeles');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Act - Payment Step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'L Bob Rife');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Act - Review Step
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert
      await waitFor(() => {
        expect(screen.getByRole('status')).toHaveTextContent(/order confirmed/i);
        expect(screen.getByText('ORD-12345')).toBeInTheDocument();
      });
    });
  });

  describe('Form Validation - Shipping', () => {
    it('should display error when street address is empty', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('should display error for invalid ZIP code format', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'ABCDE');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Form Validation - Payment', () => {
    it('should reject invalid card number', async () => {
      const user = userEvent.setup();
      renderCheckout();
      await fillValidShipping(user);

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
    });

    it('should reject invalid expiry format', async () => {
      const user = userEvent.setup();
      renderCheckout();
      await fillValidShipping(user);

      await user.type(screen.getByLabelText(/expiry/i), '13/25');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid expiry/i)).toBeInTheDocument();
    });
  });

  describe('Error States and Recovery', () => {
    it('should display payment failure and allow retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      renderCheckout();
      await completeToReviewStep(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });

      mockProcessPayment.mockResolvedValueOnce({ orderId: 'ORD-RETRY' });
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText('ORD-RETRY')).toBeInTheDocument();
      });
    });
  });

  describe('Loading and Disabled States', () => {
    it('should disable buttons and show loading during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      const user = userEvent.setup();
      renderCheckout();
      await completeToReviewStep(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  describe('Accessibility Requirements', () => {
    it('should have no accessibility violations on shipping step', async () => {
      const { container } = renderCheckout();
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('should announce current step in navigation', () => {
      renderCheckout();
      expect(screen.getByText('Shipping').closest('li')).toHaveAttribute('aria-current', 'step');
    });

    it('should announce errors with role="alert"', async () => {
      const user = userEvent.setup();
      renderCheckout();
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getAllByRole('alert').length).toBeGreaterThan(0);
    });
  });

  describe('Edge Cases', () => {
    it('should display empty cart message when no items', () => {
      renderCheckout([]);

      expect(screen.getByRole('alert')).toHaveTextContent(/your cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });

    it('should allow navigation back to previous steps', async () => {
      const user = userEvent.setup();
      renderCheckout();
      await fillValidShipping(user);

      await user.click(screen.getByRole('button', { name: /back/i }));

      expect(screen.getByLabelText(/street address/i)).toBeInTheDocument();
    });
  });
});

// Helper functions
async function fillValidShipping(user: ReturnType<typeof userEvent.setup>) {
  await user.type(screen.getByLabelText(/street address/i), '123 Test St');
  await user.type(screen.getByLabelText(/city/i), 'Test City');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip code/i), '90210');
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function completeToReviewStep(user: ReturnType<typeof userEvent.setup>) {
  await fillValidShipping(user);
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'Test User');
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
